-- Slice 1 / T1.20. Invitation columns generated by drizzle-kit; the rest is hand-written.
ALTER TABLE "invitation" ADD COLUMN "name" text;--> statement-breakpoint
ALTER TABLE "invitation" ADD COLUMN "manager_id" uuid;--> statement-breakpoint
ALTER TABLE invitation ADD CONSTRAINT invitation_manager_fk FOREIGN KEY (org_id, manager_id)
  REFERENCES member (org_id, user_id) ON DELETE SET NULL (manager_id);--> statement-breakpoint

-- crm_app may read the names and emails of its own org's members, nothing else of "user" (no credentials, no
-- other org). The policy leans on member's own RLS, so "is a member" means "is a member of the current org".
ALTER TABLE "user" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "user" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY auth_access ON "user" TO crm_auth USING (true) WITH CHECK (true);--> statement-breakpoint
CREATE POLICY org_member ON "user" FOR SELECT TO crm_app USING (EXISTS (SELECT 1 FROM member m WHERE m.user_id = "user".id));--> statement-breakpoint
GRANT SELECT (id, name, email) ON "user" TO crm_app;--> statement-breakpoint

-- One row per member of the current org (SCHEMA § user). security_invoker: the caller's grants and RLS apply.
CREATE VIEW org_users WITH (security_invoker = true) AS
  SELECT u.id, u.name, u.email, m.role, m.manager_id, m.status, m.created_at
  FROM member m JOIN "user" u ON u.id = m.user_id;--> statement-breakpoint
GRANT SELECT ON org_users TO crm_app;--> statement-breakpoint

-- US-03 writes, Admin-only in the database too (AC-35): invite, and change role, manager or status.
GRANT INSERT ON invitation TO crm_app;--> statement-breakpoint
GRANT UPDATE (role, manager_id, status) ON member TO crm_app;--> statement-breakpoint
CREATE POLICY admin_only_insert ON invitation AS RESTRICTIVE FOR INSERT TO crm_app WITH CHECK (current_setting('app.role', true) = 'admin');--> statement-breakpoint
CREATE POLICY admin_only_update ON member AS RESTRICTIVE FOR UPDATE TO crm_app USING (current_setting('app.role', true) = 'admin');
